script:
frappe.ui.form.on('User', {
    refresh: function(frm) {
        setTimeout(function() {
            hide_roles();
            filter_modules();
            hide_bulk_buttons();
        }, 700);
    }
});

function hide_roles() {
    const blacklist = ['System Manager', 'Script Manager'];

    blacklist.forEach(function(role) {
        $(`[data-fieldname="roles_html"] input[data-unit="${role}"]`)
            .closest('div.unit-checkbox')
            .hide();
    });
}

function filter_modules() {
    const whitelist = [
        'Accounts',
        'Buying',
        'Manufacturing',
        'Selling',
        'Stock',
        'Quality Management'
    ];

    $('[data-fieldname="modules_html"] div.unit-checkbox').each(function() {
        const unit = $(this).find('input').data('unit');
        if (!whitelist.includes(unit)) {
            $(this).hide();
        }
    });
}

function hide_bulk_buttons() {
    $('div.bulk-select-options').hide();
}

frappe.ui.form.on('Production Plan', {
    get_sales_orders: function(frm) {
        frappe.call({
            method: 'get_open_sales_orders',
            doc: frm.doc,
            callback: function(r) {
                refresh_field('sales_orders');

                frm.clear_table('prod_plan_references');
                frappe.call({
                    method: 'get_items',
                    freeze: true,
                    doc: frm.doc,
                    callback: function() {
                        refresh_field('po_items');

                        frm.dirty();
                        frappe.call({
                            method: 'get_sub_assembly_items',
                            freeze: true,
                            doc: frm.doc,
                            callback: function() {
                                refresh_field('sub_assembly_items');
                            }
                        });
                    }
                });
            }
        });
    }
});

frappe.ui.form.on('Production Plan RM Override', {
    production_plan_item: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.production_plan_item) return;
        frappe.db.get_value('Production Plan Item', row.production_plan_item, 'item_code')
            .then(function(r) {
                frappe.model.set_value(cdt, cdn, 'fg_item', r.message ? r.message.item_code : '');
            });
    }
});

frappe.ui.form.on('BOM Creator', {
    setup: function(frm) {
        frappe.ui.form.handlers['BOM Creator']['make_new_entry'] = [
            function(frm) {
                let dialog = new frappe.ui.Dialog({
                    title: __('Multi-level BOM Creator'),
                    fields: [
                        {
                            label: __('Customer'),
                            fieldtype: 'Link',
                            fieldname: 'customer',
                            options: 'Customer',
                            reqd: 1,
                        },
                        { fieldtype: 'Section Break' },
                        {
                            label: __('Item Name'),
                            fieldtype: 'Data',
                            fieldname: 'item_name',
                            reqd: 1,
                        },
                    ],
                    primary_action_label: __('Create'),
                    primary_action: function(values) {
                        dialog.hide();

                        frappe.call({
                            method: 'iib.overrides.bom_creator.create_master_card_bom_creator',
                            args: {
                                customer: values.customer,
                                item_name: values.item_name,
                            },
                            freeze: true,
                            freeze_message: __('Creating Master Card...'),
                            callback: function(r) {
                                if (r.message && r.message.bom_creator) {
                                    frappe.set_route('Form', 'BOM Creator', r.message.bom_creator);
                                }
                            },
                            error: function() {
                                dialog.show();
                            },
                        });
                    },
                });

                dialog.show();
            }
        ];
    },

    refresh: function(frm) {
        if (frm.is_new()) return;
        frappe.require('bom_configurator.bundle.js').then(function() {
            if (!frappe.ui.BOMConfigurator) return;

            let custom_add_sub_assembly = function(node, view) {
                let self = this;
                let parent_code = node.data.value;

                let dialog = new frappe.ui.Dialog({
                    title: __('Add Sub Assembly'),
                    fields: [
                        {
                            label: __('Letter'),
                            fieldname: 'letter',
                            fieldtype: 'Data',
                            reqd: 1,
                            description: __('Single A-Z letter. New item code: ') + parent_code + '<letter>',
                        },
                        {
                            label: __('Item Group'),
                            fieldname: 'item_group',
                            fieldtype: 'Link',
                            options: 'Item Group',
                            default: 'Component',
                            reqd: 1,
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('Description'),
                            fieldname: 'item_description',
                            fieldtype: 'Link',
                            options: 'Item Description',
                            reqd: 1,
                        },
                        {
                            label: __('Stock UOM'),
                            fieldname: 'stock_uom',
                            fieldtype: 'Link',
                            options: 'UOM',
                            default: 'Pcs',
                            reqd: 1,
                        },
                        { fieldtype: 'Section Break', label: __('Item Details') },
                        {
                            label: __('Part No.'),
                            fieldname: 'custom_part_no',
                            fieldtype: 'Data',
                        },
                        {
                            label: __('Inside Measure L'),
                            fieldname: 'custom_inside_measure_l',
                            fieldtype: 'Int',
                        },
                        {
                            label: __('Inside Measure W'),
                            fieldname: 'custom_inside_measure_w',
                            fieldtype: 'Int',
                        },
                        {
                            label: __('Inside Measure H'),
                            fieldname: 'custom_inside_measure_h',
                            fieldtype: 'Int',
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('Printing'),
                            fieldname: 'custom_printing',
                            fieldtype: 'Check',
                        },
                        {
                            label: __('Colour 1'),
                            fieldname: 'custom_colour_1',
                            fieldtype: 'Link',
                            options: 'Colour 1',
                        },
                        {
                            label: __('Colour 2'),
                            fieldname: 'custom_colour_2',
                            fieldtype: 'Link',
                            options: 'Colour 2',
                        },
                        {
                            label: __('Colour 3'),
                            fieldname: 'custom_colour_3',
                            fieldtype: 'Link',
                            options: 'Colour 3',
                        },
                        {
                            label: __('Colour 4'),
                            fieldname: 'custom_colour_4',
                            fieldtype: 'Link',
                            options: 'Colour 4',
                        },
                        {
                            label: __('Colour 5'),
                            fieldname: 'custom_colour_5',
                            fieldtype: 'Link',
                            options: 'Colour 5',
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('Weight'),
                            fieldname: 'custom_weight',
                            fieldtype: 'Float',
                        },
                        { fieldtype: 'Section Break', label: __('Material Spec') },
                        {
                            label: __('Width'),
                            fieldname: 'custom_width',
                            fieldtype: 'Int',
                        },
                        {
                            label: __('Length'),
                            fieldname: 'custom_length',
                            fieldtype: 'Int',
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('D/C'),
                            fieldname: 'custom_dc',
                            fieldtype: 'Int',
                        },
                        {
                            label: __('Board Quality'),
                            fieldname: 'custom_board_quality',
                            fieldtype: 'Link',
                            options: 'Board Quality',
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('Flute'),
                            fieldname: 'custom_flute',
                            fieldtype: 'Link',
                            options: 'Flute',
                        },
                        {
                            label: __('Remark'),
                            fieldname: 'custom_remarks',
                            fieldtype: 'Data',
                        },
                        { fieldtype: 'Section Break' },
                        {
                            fieldtype: 'Button',
                            fieldname: 'quick_add_rm',
                            label: __('+ Create Component'),
                        },
                        { fieldtype: 'Section Break', label: __('Raw Materials') },
                        {
                            label: __('Item Code'),
                            fieldname: 'rm_item_code',
                            fieldtype: 'Link',
                            options: 'Item',
                            reqd: 1,
                            change: function() {
                                let item_code = this.get_value();
                                if (!item_code) {
                                    dialog.set_value('rm_item_name', '');
                                    dialog.set_value('rm_default_material_request_type', 'Purchase');
                                    return;
                                }
                                frappe.db.get_value('Item', item_code, ['item_name', 'default_material_request_type']).then(function(r) {
                                    let item = r.message || {};
                                    dialog.set_value('rm_item_name', item.item_name || '');
                                    dialog.set_value('rm_default_material_request_type', item.default_material_request_type || 'Purchase');
                                });
                            },
                        },
                        {
                            label: __('Item Name'),
                            fieldname: 'rm_item_name',
                            fieldtype: 'Data',
                            read_only: 1,
                        },
                        { fieldtype: 'Column Break' },
                        {
                            label: __('Quantity'),
                            fieldname: 'rm_qty',
                            fieldtype: 'Float',
                            default: 1.0,
                            reqd: 1,
                        },
                        {
                            label: __('Default Material Request Type'),
                            fieldname: 'rm_default_material_request_type',
                            fieldtype: 'Select',
                            options: `Purchase
Material Transfer
Material Issue
Manufacture
Customer Provided`,
                            default: 'Purchase',
                            reqd: 1,
                        },
                    ],
                    primary_action_label: __('Add'),
                    primary_action: function(values) {
                        let letter = (values.letter || '').toUpperCase();
                        if (!/^[A-Z]$/.test(letter)) {
                            frappe.msgprint(__('Letter must be a single A-Z character.'));
                            return;
                        }
                        let new_code = parent_code + letter;

                        dialog.hide();

                        frappe.db.exists('Item', new_code).then(function(exists) {
                            if (exists) {
                                proceed(new_code);
                                return;
                            }
                            frappe.db.get_value('Item', parent_code, 'linked_customer').then(function(r) {
                                let customer = r.message ? r.message.linked_customer : null;
                                frappe.db.insert({
                                    doctype: 'Item',
                                    item_code: new_code,
                                    item_name: values.item_description,
                                    item_group: values.item_group,
                                    stock_uom: values.stock_uom,
                                    is_stock_item: 1,
                                    include_item_in_manufacturing: 1,
                                    linked_customer: customer,
                                    custom_part_no: values.custom_part_no,
                                    custom_inside_measure_l: values.custom_inside_measure_l,
                                    custom_inside_measure_w: values.custom_inside_measure_w,
                                    custom_inside_measure_h: values.custom_inside_measure_h,
                                    custom_width: values.custom_width,
                                    custom_length: values.custom_length,
                                    custom_dc: values.custom_dc,
                                    custom_board_quality: values.custom_board_quality,
                                    custom_flute: values.custom_flute,
                                    custom_remarks: values.custom_remarks,
                                    custom_printing: values.custom_printing,
                                    custom_colour_1: values.custom_colour_1,
                                    custom_colour_2: values.custom_colour_2,
                                    custom_colour_3: values.custom_colour_3,
                                    custom_colour_4: values.custom_colour_4,
                                    custom_colour_5: values.custom_colour_5,
                                    custom_weight: values.custom_weight,
                                }).then(function(item_doc) {
                                    proceed(item_doc.name);
                                }).catch(function() {
                                    dialog.show();
                                });
                            });
                        });

                        function proceed(item_code) {
                            if (!node.data.parent_id) {
                                node.data.parent_id = self.frm.doc.name;
                            }
                            frappe.call({
                                method: 'erpnext.manufacturing.doctype.bom_creator.bom_creator.add_sub_assembly',
                                args: {
                                    parent: node.data.parent_id,
                                    fg_item: node.data.value,
                                    fg_reference_id: node.data.name || self.frm.doc.name,
                                    bom_item: {
                                        item_code: item_code,
                                        qty: 1.0,
                                        items: [
                                            {
                                                item_code: values.rm_item_code,
                                                item_name: values.rm_item_name,
                                                qty: values.rm_qty,
                                                allow_alternative_item: 1,
                                                default_material_request_type: values.rm_default_material_request_type,
                                            }
                                        ],
                                    },
                                    allow_alternative_item: 1,
                                },
                                callback: function(r) {
                                    view.events.load_tree(r, node);
                                },
                            });
                        }
                    },
                });

                dialog.show();

                let $letter = dialog.fields_dict.letter.$input;
                $letter.attr('maxlength', 1);
                $letter.css('text-transform', 'uppercase');
                $letter.on('input', function() {
                    let v = ($(this).val() || '').toUpperCase().replace(/[^A-Z]/g, '');
                    if (v !== $(this).val()) $(this).val(v);
                });

                dialog.fields_dict.quick_add_rm.$input.on('click', function() {
                    let letter = (dialog.get_value('letter') || '').toUpperCase();
                    if (!/^[A-Z]$/.test(letter)) {
                        frappe.msgprint(__('Enter the Letter first.'));
                        return;
                    }
                    let c_code = parent_code + letter + '-C';

                    function set_raw_material_fields(item_name, material_request_type) {
                        dialog.set_value('rm_item_code', c_code);
                        dialog.set_value('rm_item_name', item_name || c_code);
                        dialog.set_value('rm_qty', 1.0);
                        dialog.set_value('rm_default_material_request_type', material_request_type || 'Purchase');
                    }

                    frappe.db.exists('Item', c_code).then(function(exists) {
                        if (exists) {
                            frappe.db.get_value('Item', c_code, ['item_name', 'default_material_request_type']).then(function(r) {
                                let item = r.message || {};
                                set_raw_material_fields(item.item_name || c_code, item.default_material_request_type || 'Purchase');
                            });
                            return;
                        }
                        frappe.db.get_value('Item', parent_code, 'linked_customer').then(function(r) {
                            let customer = r.message ? r.message.linked_customer : null;
                            frappe.db.insert({
                                doctype: 'Item',
                                item_code: c_code,
                                item_name: c_code,
                                item_group: 'Component',
                                stock_uom: dialog.get_value('stock_uom') || 'Pcs',
                                default_material_request_type: 'Purchase',
                                is_stock_item: 1,
                                include_item_in_manufacturing: 1,
                                linked_customer: customer,
                            }).then(function(item_doc) {
                                set_raw_material_fields(item_doc.item_name || item_doc.name, item_doc.default_material_request_type || 'Purchase');
                            });
                        });
                    });
                });
            };

            frappe.ui.BOMConfigurator.prototype.add_sub_assembly = custom_add_sub_assembly;
            let tree = frappe.views.trees && frappe.views.trees['BOM Configurator'];
            if (tree && tree.events) {
                tree.events.add_sub_assembly = custom_add_sub_assembly;
            }
        });
    }
});

frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        set_item_query(frm);
    },
    customer: function(frm) {
        set_item_query(frm);
    }
});

function set_item_query(frm) {
    frm.set_query('item_code', 'items', function() {
        return {
            query: 'iib.overrides.sales_order.item_query',
            filters: {
                customer: frm.doc.customer || ''
            }
        };
    });
}

frappe.ui.form.on('SO Batch', {
    refresh: function(frm) {
        if (frm.is_new()) {
            frappe.db.get_single_value('IIB Settings', 'default_so_warehouse')
                .then(function(warehouse) {
                    if (warehouse) {
                        frm.set_value('default_warehouse', warehouse);
                    }
                });
        }
    },
    customer: function(frm) {
        if (!frm.doc.customer) return;
        frappe.db.get_value('Customer', frm.doc.customer, ['default_currency', 'payment_terms'])
            .then(function(r) {
                if (!r.message) return;
                if (r.message.default_currency) {
                    frm.set_value('currency', r.message.default_currency);
                }
                if (r.message.payment_terms) {
                    frm.set_value('payment_terms_template', r.message.payment_terms);
                }
            });
    },
    currency: function(frm) {
        if (!frm.doc.currency) return;
        let company_currency = frappe.defaults.get_global_default('currency');
        if (frm.doc.currency === company_currency) {
            frm.set_value('conversion_rate', 1.0);
            return;
        }
        frappe.call({
            method: 'erpnext.setup.utils.get_exchange_rate',
            args: {
                from_currency: frm.doc.currency,
                to_currency: company_currency,
                transaction_date: frm.doc.transaction_date || frappe.datetime.get_today()
            },
            callback: function(r) {
                if (r.message) frm.set_value('conversion_rate', r.message);
            }
        });
    }
});

// Child table: map 0 → Set, 1 → Pcs for set_or_pcs column (supports paste)
frappe.ui.form.on('SO Batch Item', {
    set_or_pcs: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let val = String(row.set_or_pcs).trim();
        if (val === '0') {
            frappe.model.set_value(cdt, cdn, 'set_or_pcs', 'Set');
        } else if (val === '1') {
            frappe.model.set_value(cdt, cdn, 'set_or_pcs', 'Pcs');
        }
    }
});
